// ── IndexedDB wrapper for PDF binary bytes ────────────────────────────────
// localStorage (store.js) holds small JSON metadata only — PDFs can be
// several MB, well past what localStorage can safely hold. Every call is
// wrapped so a blocked/unavailable IndexedDB (private browsing, quota, an
// old WKWebView) degrades to a no-op rather than crashing the viewer.

const DB_NAME  = "atrile-scores";
const STORE    = "pdfBytes";
const VERSION  = 1;

let dbPromise = null;

function openDb() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    try {
      const req = indexedDB.open(DB_NAME, VERSION);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains(STORE)) {
          req.result.createObjectStore(STORE);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror   = () => reject(req.error);
    } catch (e) { reject(e); }
  });
  return dbPromise;
}

async function withStore(mode, fn) {
  try {
    const db = await openDb();
    return await new Promise((resolve, reject) => {
      const tx      = db.transaction(STORE, mode);
      const store   = tx.objectStore(STORE);
      const request = fn(store); // an IDBRequest
      tx.oncomplete = () => resolve(request ? request.result : undefined);
      tx.onerror    = () => reject(tx.error);
    });
  } catch {
    return null;
  }
}

export function putPdfBytes(workId, arrayBuffer) {
  return withStore("readwrite", (store) => store.put(arrayBuffer, workId));
}

export function getPdfBytes(workId) {
  return withStore("readonly", (store) => store.get(workId));
}

export function deletePdfBytes(workId) {
  return withStore("readwrite", (store) => store.delete(workId));
}
