import { useState, useMemo } from "react";
import {
  getWorks, getLists, createList, deleteList,
  addWorkToList, removeWorkFromList, deleteWork, listsContainingWork,
} from "./libraryStore";

const S = {
  es: {
    tabWorks: "Obras", tabLists: "Listas",
    noWorks: "Aún no has abierto ninguna partitura",
    noLists: "Aún no tienes listas",
    newList: "+ Nueva lista", newListPh: "Nombre de la lista…",
    back: "← Listas", empty: "Esta lista está vacía",
    addTo: "Agregar a lista", remove: "Quitar", delete: "Eliminar",
    confirmDeleteWork: "¿Eliminar esta partitura de la biblioteca?",
    confirmDeleteList: "¿Eliminar esta lista?",
    rename: "Renombrar",
  },
  en: {
    tabWorks: "Works", tabLists: "Lists",
    noWorks: "No scores opened yet",
    noLists: "No lists yet",
    newList: "+ New list", newListPh: "List name…",
    back: "← Lists", empty: "This list is empty",
    addTo: "Add to list", remove: "Remove", delete: "Delete",
    confirmDeleteWork: "Delete this score from the library?",
    confirmDeleteList: "Delete this list?",
    rename: "Rename",
  },
};

const row = { display: "flex", alignItems: "center", gap: 8, background: "rgba(255,255,255,0.05)", borderRadius: 9, padding: "9px 12px", marginBottom: 6 };
const btn = { background: "rgba(74,124,89,0.7)", color: "#fff", border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 };
const btnGhost = { background: "transparent", color: "#8fbc8f", border: "1px solid rgba(74,124,89,0.5)", borderRadius: 7, padding: "5px 9px", cursor: "pointer", fontSize: 11 };
const btnDanger = { background: "transparent", color: "#fca5a5", border: "none", cursor: "pointer", fontSize: 16, padding: "0 4px" };

export default function LibraryView({ lang = "es", onOpenWork, onClose }) {
  const L = S[lang] || S.es;
  const [tab, setTab]           = useState("works"); // "works" | "lists"
  const [activeList, setActiveList] = useState(null); // list id, when drilled in
  const [newListName, setNewListName] = useState("");
  const [pickerFor, setPickerFor]     = useState(null); // workId while the add-to-list popover is open
  const [, forceRefresh] = useState(0);
  const refresh = () => forceRefresh(n => n + 1);

  const works = getWorks();
  const lists = getLists();
  const workList = useMemo(
    () => Object.values(works).sort((a, b) => (b.lastOpenedAt || 0) - (a.lastOpenedAt || 0)),
    [works]
  );
  const currentList = activeList ? lists.find(l => l.id === activeList) : null;

  const handleCreateList = () => {
    if (!newListName.trim()) return;
    createList(newListName.trim());
    setNewListName("");
    refresh();
  };

  const handleDeleteWork = (workId) => {
    if (!window.confirm(L.confirmDeleteWork)) return;
    deleteWork(workId);
    refresh();
  };

  const WorkRow = ({ work }) => (
    <div style={row}>
      <div style={{ flex: 1, minWidth: 0, cursor: "pointer" }} onClick={() => onOpenWork(work)}>
        <div style={{ color: "#e8e4d8", fontSize: 13, fontWeight: 700, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{work.title || work.fileName}</div>
        <div style={{ color: "#6b8f6b", fontSize: 11 }}>{work.source}{work.pages ? ` · ${work.pages}p` : ""}</div>
      </div>
      <button style={btnGhost} onClick={() => setPickerFor(work.id)}>{L.addTo}</button>
      <button style={btnDanger} onClick={() => handleDeleteWork(work.id)}>×</button>
    </div>
  );

  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 50, background: "rgba(8,16,10,0.97)", backdropFilter: "blur(10px)", display: "flex", flexDirection: "column", color: "#e8e4d8" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 14px", borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
        {activeList ? (
          <button onClick={() => setActiveList(null)} style={{ ...btnGhost, flexShrink: 0 }}>{L.back}</button>
        ) : (
          <div style={{ display: "flex", gap: 6 }}>
            <button onClick={() => setTab("works")} style={tab === "works" ? btn : btnGhost}>{L.tabWorks}</button>
            <button onClick={() => setTab("lists")} style={tab === "lists" ? btn : btnGhost}>{L.tabLists}</button>
          </div>
        )}
        <div style={{ flex: 1 }} />
        <button onClick={onClose} style={{ background: "none", border: "none", color: "#8fbc8f", fontSize: 20, cursor: "pointer", lineHeight: 1 }}>×</button>
      </div>

      <div style={{ flex: 1, overflowY: "auto", padding: 14 }}>
        {/* ── Works tab ── */}
        {!activeList && tab === "works" && (
          workList.length
            ? workList.map(w => <WorkRow key={w.id} work={w} />)
            : <div style={{ color: "#6b8f6b", fontSize: 13, textAlign: "center", padding: 24 }}>{L.noWorks}</div>
        )}

        {/* ── Lists tab ── */}
        {!activeList && tab === "lists" && (
          <>
            <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
              <input value={newListName} onChange={e => setNewListName(e.target.value)}
                onKeyDown={e => e.key === "Enter" && handleCreateList()}
                placeholder={L.newListPh}
                style={{ flex: 1, padding: "8px 10px", borderRadius: 8, border: "1px solid #4a7c59", background: "rgba(255,255,255,0.05)", color: "#e8e4d8", fontSize: 13, outline: "none" }} />
              <button onClick={handleCreateList} style={btn}>{L.newList}</button>
            </div>
            {lists.length
              ? lists.map(l => (
                <div key={l.id} style={row}>
                  <div style={{ flex: 1, cursor: "pointer" }} onClick={() => setActiveList(l.id)}>
                    <div style={{ color: "#e8e4d8", fontSize: 13, fontWeight: 700 }}>{l.name}</div>
                    <div style={{ color: "#6b8f6b", fontSize: 11 }}>{l.workIds.length}</div>
                  </div>
                  <button style={btnDanger} onClick={() => { if (window.confirm(L.confirmDeleteList)) { deleteList(l.id); refresh(); } }}>×</button>
                </div>
              ))
              : <div style={{ color: "#6b8f6b", fontSize: 13, textAlign: "center", padding: 24 }}>{L.noLists}</div>}
          </>
        )}

        {/* ── Drilled into one list ── */}
        {activeList && currentList && (
          <>
            <div style={{ color: "#8fbc8f", fontSize: 15, fontWeight: 700, marginBottom: 10 }}>{currentList.name}</div>
            {currentList.workIds.length
              ? currentList.workIds.map(id => works[id]).filter(Boolean).map(w => (
                <div key={w.id} style={row}>
                  <div style={{ flex: 1, minWidth: 0, cursor: "pointer" }} onClick={() => onOpenWork(w)}>
                    <div style={{ color: "#e8e4d8", fontSize: 13, fontWeight: 700, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{w.title || w.fileName}</div>
                  </div>
                  <button style={btnGhost} onClick={() => { removeWorkFromList(activeList, w.id); refresh(); }}>{L.remove}</button>
                </div>
              ))
              : <div style={{ color: "#6b8f6b", fontSize: 13, textAlign: "center", padding: 24 }}>{L.empty}</div>}
          </>
        )}
      </div>

      {/* ── Add-to-list popover ── */}
      {pickerFor && (
        <ListPickerPopover
          lang={lang}
          workId={pickerFor}
          onClose={() => { setPickerFor(null); refresh(); }}
        />
      )}
    </div>
  );
}

function ListPickerPopover({ lang, workId, onClose }) {
  const L = S[lang] || S.es;
  const lists = getLists();
  const inLists = useMemo(() => new Set(listsContainingWork(workId).map(l => l.id)), [workId]);
  const [, forceRefresh] = useState(0);

  const toggle = (listId) => {
    if (inLists.has(listId)) removeWorkFromList(listId, workId);
    else addWorkToList(listId, workId);
    forceRefresh(n => n + 1);
  };

  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 60, background: "rgba(0,0,0,0.55)", display: "flex", alignItems: "center", justifyContent: "center" }}
      onClick={onClose}>
      <div style={{ background: "#132018", borderRadius: 14, padding: 16, width: "min(320px, calc(100vw - 32px))", maxHeight: "70vh", overflowY: "auto" }}
        onClick={e => e.stopPropagation()}>
        <div style={{ color: "#8fbc8f", fontWeight: 700, marginBottom: 10 }}>{L.addTo}</div>
        {lists.length === 0 && <div style={{ color: "#6b8f6b", fontSize: 13 }}>{L.noLists}</div>}
        {lists.map(l => (
          <label key={l.id} style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 0", color: "#e8e4d8", fontSize: 13, cursor: "pointer" }}>
            <input type="checkbox" checked={inLists.has(l.id)} onChange={() => toggle(l.id)} style={{ accentColor: "#4a7c59" }} />
            {l.name}
          </label>
        ))}
        <button onClick={onClose} style={{ ...btn, width: "100%", marginTop: 10 }}>OK</button>
      </div>
    </div>
  );
}
