// ── IMSLP search + direct PDF download ────────────────────────────────────
// IMSLP's MediaWiki instance doesn't send Access-Control-Allow-Origin (even
// with the standard MediaWiki `origin=*` CORS param — verified: absent from
// its response headers), so every request goes through a third-party proxy.
// corsproxy.io's old anonymous "paste a URL after /?" endpoint was shut down
// (confirmed: it now returns 403 "keyless_legacy_url... use the CORSPROXY
// API with an API key") — do not reintroduce it without a paid key. The
// fallbacks below are free, no-key anonymous proxies as of this writing;
// since any of them can go down independently, keep this a short ordered
// list rather than a single hardcoded one.
//
// Direct download has no browser session/cookies, so country-gated or
// login-walled works will fail here; callers should fall back to opening
// the IMSLP page in a browser tab in that case (where the user's own
// session/cookies can get them through).
const PROXIES = [
  (url) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(url)}`,
  (url) => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
];

async function proxiedFetch(url, { asText = false, timeoutMs = 9000 } = {}) {
  for (const makeProxyUrl of PROXIES) {
    try {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), timeoutMs);
      const res = await fetch(makeProxyUrl(url), { signal: ctrl.signal });
      clearTimeout(t);
      if (!res.ok) continue;
      return asText ? await res.text() : await res.arrayBuffer();
    } catch { /* try next proxy */ }
  }
  return null;
}

export async function searchImslp(query) {
  if (!query.trim()) return [];
  const apiUrl = `https://imslp.org/api.php?action=query&list=search&srsearch=${encodeURIComponent(query)}&srlimit=12&srnamespace=0&format=json`;
  const text = await proxiedFetch(apiUrl, { asText: true });
  if (!text) return [];
  try {
    const data = JSON.parse(text);
    return data?.query?.search || [];
  } catch { return []; }
}

// Finds the first scan-file download link on an IMSLP wiki page.
function findPdfLink(html) {
  try {
    const doc = new DOMParser().parseFromString(html, "text/html");
    const redirector = doc.querySelector('a[href*="/wiki/Special:ImagefromIndex/"]');
    if (redirector) return new URL(redirector.getAttribute("href"), "https://imslp.org").toString();
  } catch { /* fall through to regex */ }
  const m = html.match(/href="([^"]+\.pdf)"/i);
  return m ? new URL(m[1], "https://imslp.org").toString() : null;
}

// Downloads a result's PDF bytes directly, so it can be opened in the
// viewer with no manual "go to IMSLP, download, come back" round trip.
// Returns null on failure (expected for restricted/gated works) — callers
// should fall back to opening the wiki page in a browser tab.
export async function fetchImslpPdf(title) {
  const pageUrl = `https://imslp.org/wiki/${encodeURIComponent(title.replace(/ /g, "_"))}`;
  const html = await proxiedFetch(pageUrl, { asText: true });
  if (!html) return null;

  let pdfUrl = findPdfLink(html);
  if (!pdfUrl) return null;

  let bytes = await proxiedFetch(pdfUrl);
  if (!bytes) return null;

  // A non-PDF response (e.g. a rights-acceptance interstitial HTML page)
  // starts with "<" instead of the PDF magic bytes "%PDF" — try parsing it
  // as HTML once more before giving up.
  const head = new Uint8Array(bytes.slice(0, 4));
  const isPdf = head[0] === 0x25 && head[1] === 0x50 && head[2] === 0x44 && head[3] === 0x46; // %PDF
  if (!isPdf) {
    const text = new TextDecoder().decode(bytes);
    const secondUrl = findPdfLink(text);
    if (!secondUrl || secondUrl === pdfUrl) return null;
    bytes = await proxiedFetch(secondUrl);
    if (!bytes) return null;
    const head2 = new Uint8Array(bytes.slice(0, 4));
    if (!(head2[0] === 0x25 && head2[1] === 0x50 && head2[2] === 0x44 && head2[3] === 0x46)) return null;
  }

  return bytes;
}

export function imslpWikiUrl(title) {
  return `https://imslp.org/wiki/${encodeURIComponent(title.replace(/ /g, "_"))}`;
}

// Direct IMSLP search (no proxy) — the UI's last-resort fallback when every
// proxy is down (free public proxies are flaky; this happens in practice).
export function imslpSearchUrl(query) {
  return `https://imslp.org/index.php?title=Special:Search&search=${encodeURIComponent(query)}`;
}
